using System;
using System.Linq;
namespace FocoLocal {
 public class Tests {
  static int checks=0;
  static void Check(bool condition,string name) {if(!condition)throw new Exception("FAIL: "+name);checks++;Console.WriteLine("OK: "+name);}
  static void Invalid(string domain) {bool failed=false;try{Engine.Normalize(domain);}catch{failed=true;}Check(failed,"Reject "+domain);}
  public static void Main() {
   Check(Engine.Normalize("https://WWW.Example.com/")=="www.example.com","Normalize domain");
   foreach(var d in new[]{"*.com","127.0.0.1","https://example.com/path","https://example.com?x=1","https://user@example.com","https://example.com:9999","example.com#x"})Invalid(d);
   Check(Engine.Match("sub.example.com","example.com")&&!Engine.Match("notexample.com","example.com"),"Subdomain boundary");
   var r=new Rule {name="Example",domains=new[]{"example.com"},always=false,minutes=1,start=9*60,end=17*60,days=1<<1};
   var monday=new DateTime(2026,10,26,10,0,0,DateTimeKind.Local);
   Check(Engine.InWindow(r,monday),"Selected weekday inside range");
   Check(!Engine.InWindow(r,monday.AddDays(1)),"Unselected weekday");
   Check(!Engine.InWindow(r,monday.Date.AddHours(17)),"End boundary exclusive");
   Check(Engine.InWindow(r,monday.Date.AddHours(9)),"Start boundary inclusive");
   r.start=22*60;r.end=6*60;
   Check(Engine.InWindow(r,monday.Date.AddHours(23)),"Overnight start day");
   Check(Engine.InWindow(r,monday.Date.AddDays(1).AddHours(5)),"Overnight following day");
   Check(!Engine.InWindow(r,monday.Date.AddHours(5)),"Overnight not previous unselected day");
   r.start=r.end=0;r.days=127;
   var s=new State();s.rules.Add(r);DateTime utc=monday.ToUniversalTime();double now=Engine.Stamp(utc);
   Engine.Charge(s,"example.com",now-2,now,utc);Check(s.usage[r.id]==2,"Foreground usage");
   Engine.Charge(s,"example.com",now-1,now+1,utc.AddSeconds(1));Check(s.usage[r.id]==3,"No double counting between browsers");
   Engine.Charge(s,"",now+1,now+3,utc.AddSeconds(3));Check(s.usage[r.id]==3,"Inactive tab ignored");
   Engine.Charge(s,"example.com",now+3,now+100,utc.AddSeconds(100));Check(s.usage[r.id]==3,"Suspend interval ignored");
   s.usage[r.id]=59;Engine.Charge(s,"example.com",now+100,now+102,utc.AddSeconds(102));Check(s.usage[r.id]==60,"Quota capped");
   Check(Engine.Reason(r,s,monday)=="Limite diário atingido","Quota blocks");
   Engine.Rollover(s,monday.AddDays(-1));Check(s.usage[r.id]==60,"Clock backwards does not reset quota");
   Engine.Rollover(s,monday.AddDays(1));Check(s.usage.Count==0,"Next day resets quota");
   s=new State();s.rules.Add(r);var midnight=monday.Date.AddDays(1).AddSeconds(1).ToUniversalTime();now=Engine.Stamp(midnight);Engine.Charge(s,"example.com",now-2,now,midnight);Check(s.usage[r.id]==1,"Midnight splits usage");
   r.always=true;Check(Engine.Reason(r,s,monday)=="Bloqueio permanente","Always block");
   r.always=false;r.blockWindow=true;r.start=750;r.end=1110;r.days=127;r.minutes=0;s.usage.Clear();
   Check(Engine.Reason(r,s,monday.Date.AddHours(12).AddMinutes(29))=="Permitido agora","Work block before 12:30");
   Check(Engine.Reason(r,s,monday.Date.AddHours(12.5))=="Horário de bloqueio","Work block starts at 12:30");
   Check(Engine.Reason(r,s,monday.Date.AddHours(18).AddMinutes(29))=="Horário de bloqueio","Work block until 18:30");
   Check(Engine.Reason(r,s,monday.Date.AddHours(18.5))=="Permitido agora","Work block ends at 18:30");
   Check(Engine.Reason(r,s,monday.AddDays(6).Date.AddHours(13))=="Horário de bloqueio","Work block every day including Sunday");
   r.days=1<<1;Check(Engine.Reason(r,s,monday.AddDays(1).Date.AddHours(13))=="Permitido agora","Unselected day allowed in block mode");
   r.start=22*60;r.end=6*60;Check(Engine.Reason(r,s,monday.Date.AddDays(1).AddHours(5))=="Horário de bloqueio","Block mode overnight");
   Engine.StartFocus(s,new[]{r.id},120,monday.ToUniversalTime());
   Check(Engine.Reason(r,s,monday.AddMinutes(119)).StartsWith("Sessão de foco"),"Study blocks for two hours");
   Check(Engine.Reason(r,s,monday.AddMinutes(120))=="Permitido agora","Study expires exactly on deadline");
   double deadline=r.focusUntil;Engine.StartFocus(s,new[]{r.id},60,monday.ToUniversalTime());Check(r.focusUntil==deadline,"Starting shorter focus does not shorten deadline");
   Engine.StartFocus(s,new[]{r.id},180,monday.ToUniversalTime());Check(r.focusUntil==Engine.Stamp(monday.ToUniversalTime().AddHours(3)),"Three-hour focus preset");
   var saved=Store.Json.Serialize(s);var restored=Store.Json.Deserialize<State>(saved);Check(restored.rules[0].focusUntil==r.focusUntil&&restored.rules[0].blockWindow,"Focus and daily schedule survive restart");
   Engine.Rollover(restored,monday.AddDays(1));Check(restored.rules[0].focusUntil==r.focusUntil,"Midnight does not reset focus deadline");
   r.start=750;r.end=1110;Check(Engine.Reason(r,s,monday.AddHours(3))=="Horário de bloqueio","Expired focus preserves work block");
   r.blockWindow=false;r.start=r.end=0;r.minutes=1;s.usage[r.id]=60;Check(Engine.Reason(r,s,monday.AddHours(4))=="Limite diário atingido","Expired focus preserves daily quota");
   bool invalidSession=false;try{Engine.StartFocus(s,new[]{r.id},0,monday.ToUniversalTime());}catch{invalidSession=true;}Check(invalidSession,"Reject zero-duration focus");
   var old=Store.Json.Deserialize<State>("{\"version\":1,\"rules\":[{\"id\":\"old\",\"always\":false,\"start\":0,\"end\":0,\"days\":127,\"minutes\":0}]}");Check(!old.rules[0].blockWindow&&old.rules[0].focusUntil==0,"Old rules keep original meaning");
   var q=new Rule {name="Cota de trabalho",domains=new[]{"example.com"},always=false,windowQuota=true,minutes=20,start=750,end=1110,days=127};
   s=new State();s.rules.Add(q);s.usage[q.id]=3600;s.day=monday.ToString("yyyy-MM-dd");
   now=Engine.Stamp(monday.ToUniversalTime());Engine.Charge(s,"example.com",now-2,now,monday.ToUniversalTime());
   Check(Engine.WindowUsed(q,s,monday)==0 && s.usage[q.id]==3602,"Free outside time never spends window quota or caps daily total");
   var during=monday.Date.AddHours(13);now=Engine.Stamp(during.ToUniversalTime());Engine.Charge(s,"example.com",now-2,now,during.ToUniversalTime());
   Check(Engine.WindowUsed(q,s,during)==2,"Window consumes only active seconds within its bounds");
   s.windowUsage[Engine.WindowKey(q,monday)]=1199;Engine.Charge(s,"example.com",now,now+2,during.ToUniversalTime().AddSeconds(2));
   Check(Engine.WindowUsed(q,s,during)==1200,"Window quota caps at editable 20 minutes");
   Check(Engine.Reason(q,s,during)=="Cota da faixa esgotada","Window blocks after quota consumed");
   Check(Engine.Reason(q,s,monday.Date.AddHours(18.5))=="Permitido agora","Free again at 18:30 despite exhausted quota");
   Check(Engine.Reason(q,s,monday.Date.AddHours(12))=="Permitido agora","Free before 12:30 despite quota state");
   Check(Engine.Reason(q,s,during.AddDays(1))=="Permitido agora" && Engine.WindowUsed(q,s,during.AddDays(1))==0,"Fresh quota next daily window");
   q.minutes=25;Check(Engine.Reason(q,s,during)=="Permitido agora" && Engine.WindowUsed(q,s,during)==1200,"Editing allowance preserves consumption and permits extra five minutes");
   q.minutes=10;Check(Engine.Reason(q,s,during)=="Cota da faixa esgotada","Reducing allowance immediately respects existing usage");q.minutes=20;
   q.days=1<<1;Check(Engine.Reason(q,s,during.AddDays(1))=="Permitido agora","Unselected days remain free");q.days=127;
   s=new State();s.rules.Add(q);var boundary=monday.Date.AddHours(12.5).AddSeconds(1);now=Engine.Stamp(boundary.ToUniversalTime());Engine.Charge(s,"example.com",now-2,now,boundary.ToUniversalTime());
   Check(Engine.WindowUsed(q,s,boundary)==1,"Entry sample excludes seconds before window begins");
   boundary=monday.Date.AddHours(18.5).AddSeconds(1);now=Engine.Stamp(boundary.ToUniversalTime());Engine.Charge(s,"example.com",now-2,now,boundary.ToUniversalTime());
   Check(Engine.WindowUsed(q,s,boundary)==2,"Exit sample includes only seconds before window ends");
   q.start=1320;q.end=360;s=new State();s.rules.Add(q);boundary=monday.Date.AddDays(1).AddSeconds(1);now=Engine.Stamp(boundary.ToUniversalTime());Engine.Charge(s,"example.com",now-2,now,boundary.ToUniversalTime());
   Check(Engine.WindowUsed(q,s,boundary)==2,"Overnight quota survives midnight and counts both sides");
   s.windowUsage[Engine.WindowKey(q,monday)]=1200;Check(Engine.Reason(q,s,boundary.AddHours(1))=="Cota da faixa esgotada","Midnight cannot replenish an overnight quota");
   Check(Engine.Reason(q,s,monday.Date.AddDays(1).AddHours(6))=="Permitido agora","Overnight exhausted quota releases at window end");
   Check(Engine.WindowUsed(q,s,monday.Date.AddDays(1).AddHours(22))==0,"Next overnight window starts fresh");
   s=new State();s.rules.Add(q);boundary=monday.Date.AddDays(1);now=Engine.Stamp(boundary.ToUniversalTime());Engine.Charge(s,"example.com",now-1,now,boundary.ToUniversalTime());Check(Engine.WindowUsed(q,s,boundary)==1,"Exact midnight sample retains previous window second");
   Engine.StartFocus(s,new[]{q.id},120,boundary.ToUniversalTime());Check(Engine.Reason(q,s,boundary).StartsWith("Sessão de foco"),"Study block takes priority over window allowance");
   var restoredQuota=Store.Json.Deserialize<State>(Store.Json.Serialize(s));Check(restoredQuota.rules[0].windowQuota&&restoredQuota.windowUsage.Count==1,"Window quotas survive persistence");
   q.minutes=0;bool invalidQuota=false;try{Engine.Validate(q);}catch{invalidQuota=true;}Check(invalidQuota,"Zero-minute window allowance rejected");
   Check(!old.rules[0].windowQuota&&old.windowUsage!=null,"Old data initializes independent quota storage");
   var pausing=new State();var twitter=new Rule{name="Twitter",domains=new[]{"twitter.com","x.com"}};var tiktok=new Rule{name="TikTok",domains=new[]{"tiktok.com"}};pausing.rules.Add(twitter);pausing.rules.Add(tiktok);
   var lease=Engine.RequestPause(pausing,twitter,utc);Check(lease.startsAt==Engine.Stamp(utc.AddMinutes(30))&&lease.endsAt==Engine.Stamp(utc.AddMinutes(40)),"Pause waits 30 min and lasts 10 min");
   Check(!Engine.Paused(pausing,twitter,utc.AddMinutes(30).AddMilliseconds(-1)),"Blocked before pause begins");
   Check(Engine.Paused(pausing,twitter,utc.AddMinutes(30)),"Pause begins exactly at boundary");
   Check(!Engine.Paused(pausing,twitter,utc.AddMinutes(40)),"Pause ends exactly at boundary");
   Check(Engine.Reason(twitter,pausing,utc.AddMinutes(35).ToLocalTime())=="Permitido agora","Permanent extension block yields to temporary pause");
   Engine.RequestPause(pausing,tiktok,utc);Check(pausing.pauses.Count==2,"Different sites have independent requests");
   bool rejected=false;try{Engine.RequestPause(pausing,twitter,utc.AddHours(24));}catch{rejected=true;}Check(rejected,"24 hours starts at release time, not midnight or request time");
   var replacement=new Rule{name="Renamed",domains=new[]{"mobile.x.com"}};rejected=false;try{Engine.RequestPause(pausing,replacement,utc.AddHours(1));}catch{rejected=true;}Check(rejected,"Recreating rule and using Twitter alias cannot reset cooldown");
   lease.cancelled=true;Check(!Engine.Paused(pausing,twitter,utc.AddMinutes(35)),"Cancellation immediately reblocks");
   rejected=false;try{Engine.RequestPause(pausing,twitter,utc.AddMinutes(35));}catch{rejected=true;}Check(rejected,"Cancellation preserves cooldown");
   var pauseSaved=Store.Json.Deserialize<State>(Store.Json.Serialize(pausing));Check(pauseSaved.pauses[0].cancelled&&pauseSaved.pauses[0].nextAt==lease.nextAt,"Pause cancellation and cooldown survive restart");
   Check(Engine.RequestPause(pausing,twitter,utc.AddHours(24).AddMinutes(30))!=null,"New request accepted at exact rolling 24h boundary");
   twitter.archived=true;var archived=Engine.View(pausing,utc);Check(archived.rules.Count==1&&archived.archivedRules.Count==1&&!archived.archivedRules[0].blocked,"Archived rules omitted from extension enforcement");
   Engine.Charge(pausing,"x.com",Engine.Stamp(utc)-1,Engine.Stamp(utc),utc);Check(!pausing.usage.ContainsKey(twitter.id),"Archived rule is not metered");
   twitter.archived=false;Check(Engine.View(pausing,utc).rules.Count==2&&twitter.domains.Length==2,"Reactivation preserves rule configuration");
   Check(!old.rules[0].archived&&old.pauses!=null,"Old data defaults active and initializes pauses");
   var guard=new GuardState();var request=new GuardRequest{id=Guid.NewGuid().ToString("N"),domains=new[]{"x.com"}};var gp=GuardHosts.Request(guard,request,utc);
   Check(GuardHosts.Request(guard,request,utc.AddSeconds(5)).id==gp.id&&guard.pauses.Count==1,"Service request retry idempotent");
   string original="127.0.0.1 localhost\r\n# outside\r\n"+GuardHosts.Begin+"\r\n0.0.0.0 x.com\r\n:: x.com\r\n0.0.0.0 www.twitter.com\r\n:: www.twitter.com\r\n0.0.0.0 tiktok.com\r\n# keep\r\n"+GuardHosts.End+"\r\n# tail\r\n";
   Check(GuardHosts.Transform(original,guard,gp.startsAt-1,false)==original,"Windows hosts unchanged during waiting period");
   string released=GuardHosts.Transform(original,guard,gp.startsAt,false);Check(!released.Contains("0.0.0.0 x.com")&&!released.Contains(":: x.com")&&!released.Contains("www.twitter.com")&&released.Contains("tiktok.com")&&released.Contains("# outside")&&released.Contains("# tail"),"Windows release removes only selected IPv4/IPv6 aliases, preserving other blocks and outside bytes");
   var guardRestart=GuardWire.Json.Deserialize<GuardState>(GuardWire.Json.Serialize(guard));string restoredHosts=GuardHosts.Transform(released,guardRestart,gp.endsAt,false);Check(restoredHosts.Contains("0.0.0.0 x.com")&&restoredHosts.Contains(":: x.com")&&restoredHosts.Contains("www.twitter.com"),"Service journal restores hosts after restart and expiry");
   GuardHosts.Finish(guardRestart,gp.endsAt,false);Check(guardRestart.held.Count==0,"Restoration journal clears only after successful hosts write");
   Check(GuardHosts.Transform(released,guard,gp.startsAt,true).Contains("0.0.0.0 x.com"),"Stopping service restores active Windows blocks");
   gp.cancelled=true;Check(GuardHosts.Transform(released,guard,gp.startsAt+1,false).Contains("0.0.0.0 x.com"),"Cancelling restores Windows block");
   rejected=false;try{GuardHosts.Request(guard,new GuardRequest{id=Guid.NewGuid().ToString("N"),domains=new[]{"twitter.com"}},utc.AddHours(1));}catch{rejected=true;}Check(rejected,"Service independently enforces alias cooldown");
   rejected=false;try{GuardHosts.Transform(GuardHosts.Begin+"\r\n",guard,gp.endsAt,false);}catch{rejected=true;}Check(rejected,"Malformed hosts block fails without modifying file");
   string absent=GuardHosts.Transform("127.0.0.1 localhost\r\n",guard,gp.endsAt,false);Check(absent.Contains("0.0.0.0 x.com"),"Journal restores captured entries if marked block was removed");
   checks+=ChangeTests.Run();Console.WriteLine(checks+" checks passed.");
  }
 }
}
